const isBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && items.every((item) => item.type === items[0].type);

/** Three alike components form a block, priced at a special base premium. */
const blockAwareBasePremium = (items: Item[]): number =>
  isBlock(items)
    ? BLOCK_BASE_PREMIUM
    : items.reduce((sum, item) => sum + basePremiumOf(item), 0);
